        ("Vm.CouldNotReadCopiedRHIWill", "{0} não pôde ser lido nem copiado ({1}). O RHI não vai salvar por cima dele: corrija ou apague o arquivo para voltar a salvar.", "{0} could not be read or copied ({1}). RHI will not save over it: fix or delete the file to save again."),
        ("Vm.CouldNotReadItsContentsWere", "{0} não pôde ser lido; o conteúdo foi copiado para {1}. O RHI não vai salvar por cima dele: corrija ou apague o arquivo para voltar a salvar.", "{0} could not be read; its contents were copied to {1}. RHI will not save over it: fix or delete the file to save again."),
        ("Vm.NotSavedCouldNotReadCopy", "Não salvo: {0} não pôde ser lido (há uma cópia em {1}). Corrija ou apague o arquivo para voltar a salvar.", "Not saved: {0} could not be read (a copy is at {1}). Fix or delete the file to save again."),
        ("Vm.NotSavedCouldNotReadFix", "Não salvo: {0} não pôde ser lido. Corrija ou apague o arquivo para voltar a salvar.", "Not saved: {0} could not be read. Fix or delete the file to save again."),
        ("Vm.GithubApiTxtCouldReadBy", "O github_api.txt podia ser lido por outros usuários deste computador; o RHI restringiu o acesso só à sua conta (chmod 600).", "github_api.txt could be read by other users on this computer; RHI restricted it to your account only (chmod 600)."),
        ("Vm.GithubApiTxtCanReadBy", "O github_api.txt pode ser lido por outros usuários e o RHI não conseguiu restringi-lo; o token não será usado até você executar chmod 600 nele.", "github_api.txt can be read by other users and RHI could not restrict it; the token is not used until you run chmod 600 on it."),
        ("Vm.IndexingStoppedAtFilesSoSome", "{0}: a indexação parou em {1} arquivos, então alguns arquivos do jogo podem não ser vistos. A pasta do jogo parece conter mais que o jogo; confira a raiz em Editar jogo.", "{0}: indexing stopped at {1} files, so some game files may not be seen. The game folder seems to hold more than the game; check the root in Edit game."),
