        ("Vm.RefreshQueued", "A atualização da biblioteca começa quando a operação atual terminar.", "The library refresh will start when the current operation finishes."),
        ("Vm.EditSavedTargetKeptPlayUsesDetectedCommand", "{0}: alterações salvas; o alvo de modificações salvo foi mantido. Jogar volta a usar o comando de execução detectado.", "{0}: changes saved; the saved modification target was kept. Play uses the detected launch command again."),
        // w3/dllnames rows
        ("Names.DllNameLabel", "Nome da DLL", "DLL name"),
        ("Names.DllNameAutomatic", "Automático ({0})", "Automatic ({0})"),
        ("Names.DllNameTipApi", "O ReShade será instalado como {0}, o arquivo que a API gráfica do jogo carrega.", "ReShade will be installed as {0}, the file the game's graphics API loads."),
        ("Names.DllNameTipManifest", "O ReShade será instalado como {0}: o manifesto do RHI define este nome para este jogo.", "ReShade will be installed as {0}: the RHI manifest sets this name for this game."),
        ("Names.DllNameTipManifestIgnored", "O ReShade será instalado como {0}. O nome {1} do manifesto do RHI não é usado: a API gráfica deste jogo não o carregaria.", "ReShade will be installed as {0}. The RHI manifest's {1} is not used: this game's graphics API would not load it."),
        ("Names.DllNameTipChosen", "O ReShade será instalado como {0}, o nome que você escolheu. Escolha Automático para voltar a {1}.", "ReShade will be installed as {0}, the name you chose. Choose Automatic to go back to {1}."),
        ("Names.DllNameTipOwnName", " Nada carrega {0} sozinho; use-o só com um mod que carregue o ReShade (OptiScaler).", " Nothing loads {0} by itself; use it only with a mod that loads ReShade (OptiScaler)."),
        ("Names.OptiScalerDllNameTip", "O OptiScaler será instalado como {0}. dxgi.dll serve para a maioria dos jogos; escolha outro nome só quando um guia deste jogo pedir.", "OptiScaler will be installed as {0}. dxgi.dll suits most games; choose another name only when a guide for this game asks for it."),
        ("Names.OptiScalerDllNameTipInstalled", "O OptiScaler está instalado como {0}. Remova o OptiScaler para instalá-lo com outro nome.", "OptiScaler is installed as {0}. Remove OptiScaler to install it under another name."),
        ("Names.OptiScalerDllNameTipHidden", " Nomes que outro componente do RHI já usa neste jogo não aparecem: {0}.", " Names another RHI component already uses on this game are not listed: {0}."),
        ("Names.DllNameTipOtherApi", " A API gráfica deste jogo pode não carregar {0}.", " This game's graphics API may not load {0}."),
        ("Names.OptionNoAddons", "Sem add-ons", "No Addons"),
        ("Names.ControlUeNotHdrMod", "⚠ Este NÃO é um mod HDR.", "⚠ This is NOT an HDR mod."),
        ("Names.ControlUeStrategies", "Ele corrige o ruído do RT com Ray Reconstruction. Duas estratégias (escolha uma; são mutuamente exclusivas):\n• Desative o denoiser de RT do jogo e use o preset M ou L do DLSS Super Resolution\n• Use Ray Reconstruction com entradas extras derivadas dos shaders do jogo (o denoiser do jogo também fica desativado — o RR exige isso)\n\nDLSS, Ray Tracing e SSAO precisam estar ativados no jogo para o Ray Reconstruction funcionar corretamente.", "It fixes RT noise using Ray Reconstruction. Two strategies (pick one; they are mutually exclusive):\n• Turn off the in-game RT denoiser and use DLSS Super Resolution preset M or L\n• Use Ray Reconstruction with extra inputs derived from the game's shaders (the game denoiser is turned off here too — RR needs that)\n\nDLSS, Ray Tracing and SSAO must all be enabled in-game for Ray Reconstruction to work correctly."),
        ("Names.ControlUeRequiredSettingsHeading", "Configurações necessárias no jogo:", "Required in-game settings:"),
        ("Names.ControlUeRequiredSettings", "DLSS ativado\nSSAO ativado\nPós-processamento em Alto\nReflexos em espaço de tela em Alto (desative o ray tracing por um momento para mudar, ou escolha o preset de renderização Alto/Ultra)\nReflexos RT ativados\nIluminação indireta difusa RT ativada\nResolução de renderização em números pares (pode ser definida no renderer.ini)", "DLSS on\nSSAO on\nPost-processing High\nScreen-space reflections High (turn ray tracing off briefly to change it, or pick the High/Ultra render preset)\nRT reflections on\nRT indirect diffuse on\nRender resolution in even numbers (can be set in renderer.ini)"),
        ("Names.ControlUeInstallAlsoHeading", "Instalar também vai:", "Installing will also:"),
        ("Names.ControlUeInstallAlso", "Atualizar nvngx_dlss.dll para a versão mais recente disponível\nInstalar nvngx_dlssd.dll (runtime do DLSS Ray Reconstruction)\nDefinir o preset HDR do renderer.ini (m_eHDRPreset) como 2\nSe FG do OptiScaler = Sim: instalar o OptiScaler Nightly build 2026-10-04 como winmm.dll (o ReShade continua dxgi.dll), com Streamline, nvngx_dlssg.dll, DLSS Enabler e as configurações de geração de quadros", "Upgrade nvngx_dlss.dll to the newest available version\nDeploy nvngx_dlssd.dll (DLSS Ray Reconstruction runtime)\nSet the renderer.ini HDR preset (m_eHDRPreset) to 2\nIf OptiScaler FG = Yes: install OptiScaler Nightly build 2026-10-04 as winmm.dll (ReShade keeps dxgi.dll), with Streamline, nvngx_dlssg.dll, DLSS Enabler and the frame generation settings"),
        // #136 Control UE OptiScaler frame generation choices.
        ("Names.ControlUeFgLabel", "Instalar FG do OptiScaler", "Install OptiScaler FG"),
        ("Names.ControlUeFgTip", "Instala o OptiScaler Nightly build 2026-10-04 com geração de quadros configurada para o Control UE, como winmm.dll, para o ReShade continuar como dxgi.dll. Fica fixo nesse build: builds mais novos quebram a geração de quadros no Control.", "Installs OptiScaler Nightly build 2026-10-04 with frame generation set up for Control UE, as winmm.dll so ReShade keeps dxgi.dll. It stays on that build: newer builds break frame generation in Control."),
        ("Names.ControlUeHdrLabel", "Usando HDR?", "Using HDR?"),
        ("Names.ControlUeHdrTip", "Sim grava FgSlHdr10=1 no reshade.ini para o shader de FG usar HDR10. Só disponível com o FG do OptiScaler.", "Yes writes FgSlHdr10=1 to reshade.ini so the FG shader uses HDR10. Only available with OptiScaler FG."),
        ("Names.No", "Não", "No"),
        ("Names.Yes", "Sim", "Yes"),
        // #97 OptiScaler per-GPU INI templates (Settings).
        ("Names.OptiScalerTemplateHeading", "Modelo de INI do OptiScaler", "OptiScaler INI template"),
        ("Names.OptiScalerGpuType", "Tipo de GPU", "GPU type"),
        ("Names.OptiScalerDlssInputs", "Entradas DLSS (AMD/Intel)", "DLSS inputs (AMD/Intel)"),
        ("Names.OpenOptiScalerTemplates", "Abrir pasta de modelos INI", "Open INI templates folder"),
        ("Names.OptiScalerTemplateNote", "Uma nova instalação do OptiScaler copia o modelo do seu canal e desta configuração de GPU como o OptiScaler.ini do jogo. Cada modelo é criado uma vez na pasta de INIs e nunca é sobrescrito, então suas edições nele valem para todas as instalações seguintes, exceto LoadAsiPlugins: o RHI sempre o liga na instalação (como o RHI original) para que os plugins do OptiScaler, como o OptiPatcher, carreguem.", "A new OptiScaler install copies the template for its channel and this GPU setup as the game's OptiScaler.ini. Each template is created once in the INIs folder and never overwritten, so your edits there apply to every later install, except LoadAsiPlugins: RHI always turns it on at install (as upstream RHI does) so OptiScaler's plugins, such as OptiPatcher, load."),
        ("Names.ControlUeLinuxNote", "O passo do preset SR no perfil do driver NVIDIA é ignorado no Linux. Remover o RenoDX restaura as DLLs e o renderer.ini anteriores, exceto o que você mesmo alterar depois da instalação.", "The NVIDIA driver-profile SR preset step is skipped on Linux. Removing RenoDX restores the previous DLLs and renderer.ini, except anything you change yourself after the install."),
        // w4/encore (#158): RTX Encore's ⚙ dialog.
        ("Ui.RtxEncoreIntro", "Geração de quadros ×2–×6 e Neural Rendering para RTX 20/30/40, num único arquivo ao lado do jogo. Menu no jogo: Insert.", "Frame generation ×2–×6 and Neural Rendering for RTX 20/30/40, in one file beside the game. In-game menu: Insert."),
        ("Ui.RtxEncoreName", "Nome do arquivo", "File name"),
        ("Ui.RtxEncoreNameTip", "O nome que o jogo carrega; version.dll é o recomendado. Nomes que outro componente do RHI já usa não aparecem. Um arquivo que já tenha esse nome é guardado como <nome>.original e volta quando você remove o RTX Encore.", "The name the game loads; version.dll is recommended. Names another RHI component already uses are not listed. A file already under that name is kept as <name>.original and put back when you remove RTX Encore."),
        ("Ui.RtxEncoreNeuralRendering", "Instalar também o arquivo de Neural Rendering da NVIDIA (310.8.0)", "Also install NVIDIA's Neural Rendering file (310.8.0)"),
        ("Ui.RtxEncoreNeuralRenderingTip", "O RTX Encore só aceita a versão 310.8.0 exata do nvngx_dlssnr.dll. Não é possível enquanto outro componente do RHI (ShortFuse, DLSS5 Feeder, OptiScaler DLSS NR/F5) tiver esse arquivo neste jogo.", "RTX Encore accepts only the exact 310.8.0 nvngx_dlssnr.dll. Not possible while another RHI component (ShortFuse, DLSS5 Feeder, OptiScaler DLSS NR/F5) has that file in this game."),
        ("Win.RtxEncoreInstalled", "Instalado: {0} como {1}. Para trocar o nome, remova e instale de novo.", "Installed: {0} as {1}. To change the name, remove it and install it again."),
        ("Ui.RtxEncoreCheck", "Verificar atualização", "Check for update"),
        ("Ui.RtxEncoreFooter", "Ainda não confirmado no Linux: geração de quadros ×3–×6 e Neural Rendering podem funcionar pelo DLSS do Proton; Smooth Motion não (precisa do driver do Windows). Use só em jogos offline: o mod roda dentro do jogo.", "Not yet confirmed on Linux: frame generation ×3–×6 and Neural Rendering may work through Proton's DLSS; Smooth Motion cannot (it needs the Windows driver). Offline games only: the mod runs inside the game."),
        // w5/update-policy rows
        // #177 Follow newest DLSS / Streamline (Settings → DLSS/Streamline).
        ("Upd.FollowHeading", "Seguir a versão mais recente", "Follow the newest version"),
        ("Upd.FollowDlss", "Seguir o DLSS mais recente (SR/RR/FG)", "Follow newest DLSS (SR/RR/FG)"),
        ("Upd.FollowStreamline", "Seguir o Streamline mais recente", "Follow newest Streamline"),
        ("Upd.FollowNote", "Desligado por padrão. Só arquivos na versão mais recente anterior mudam; versões que você escolheu ficam como estão.", "Off by default. Only files on the previous newest version change; versions you picked stay as they are."),
        ("Upd.FollowTip", "Quando o manifesto de DLSS publica uma versão mais nova, os jogos cujo arquivo está na versão mais recente anterior recebem a nova (o arquivo do jogo fica guardado como .original). Jogos numa versão escolhida por você, na versão do próprio jogo ou no DLSS 1.x ficam como estão. Verificado ao iniciar, a cada Atualizar e a cada verificação em segundo plano; cada troca aparece em Atualizações.", "When the DLSS manifest publishes a newer version, games whose file is on the previous newest version get the new one (the game's file is kept as .original). Games on a version you picked, the game's own version or DLSS 1.x stay as they are. Checked at start-up, at every Refresh and at every background check; each swap shows in Updates."),
        ("Upd.FollowSummary", "Seguir o mais recente (DLSS/Streamline): {0} arquivo(s) atualizado(s)", "Follow newest DLSS/Streamline: {0} file(s) updated"),
        ("Upd.FollowFailedPart", " · {0} falharam e ficaram como estavam (detalhes em Atualizações)", " · {0} failed and were kept as they were (details in Updates)"),
        ("Upd.FollowDeferredPart", " · {0} jogo(s) em execução ficam para a próxima verificação", " · {0} running game(s) left for the next check"),
        ("Upd.FollowBusyPart", " · {0} jogo(s) ocupado(s) no app que os instalou ficam para a próxima verificação", " · {0} game(s) busy in the app that installed them left for the next check"),
        ("Upd.FollowDownloadPart", " · {0} jogo(s) ficam para a próxima verificação: não foi possível baixar a versão mais recente (detalhes em Atualizações)", " · {0} game(s) left for the next check: the newest version could not be downloaded (details in Updates)"),
        ("Upd.FollowFailed", "Falha ao seguir o DLSS/Streamline mais recente: {0}", "Follow newest DLSS/Streamline failed: {0}"),
        // #178 update inclusion (Settings → Maintenance, card menu, dialog, component rows, Update All summary).
        ("Upd.GlobalHeading", "Atualizar tudo inclui", "Update All includes"),
        ("Upd.GlobalNote", "Componentes desmarcados ficam de fora de Atualizar tudo e das atualizações em segundo plano em todos os jogos; os botões Instalar / Remover deles continuam funcionando. Por jogo: clique com o botão direito num card → Escolher o que Atualizar tudo muda…", "Cleared components are left out of Update All and the background updates in every game; their own Install / Remove buttons still work. Per game: right-click a card → Choose what Update All changes…"),
        ("Upd.MenuItem", "Escolher o que Atualizar tudo muda…", "Choose what Update All changes…"),
        ("Upd.MenuTip", "Escolha o que Atualizar tudo e as atualizações em segundo plano podem mudar neste jogo.", "Choose what Update All and the background updates may change in this game."),
        ("Upd.DialogTitle", "Escolher o que Atualizar tudo muda — {0}", "Choose what Update All changes — {0}"),
        ("Upd.DialogIntro", "Os itens marcados fazem parte de Atualizar tudo e das atualizações em segundo plano neste jogo. Os botões Instalar / Remover de cada componente sempre funcionam.", "Ticked items take part in Update All and the background updates in this game. Each component's own Install / Remove buttons always work."),
        ("Upd.DialogDlss", "DLSS (seguir o mais recente)", "DLSS (follow newest)"),
        ("Upd.DialogStreamline", "Streamline (seguir o mais recente)", "Streamline (follow newest)"),
        ("Upd.DialogAllGamesNote", "Fora de Atualizar tudo em todos os jogos (Configurações → Manutenção): {0}", "Left out of Update All in every game (Settings → Maintenance): {0}"),
        ("Upd.InclusionSaved", "Salvo o que Atualizar tudo muda em {0}.", "Saved what Update All changes for {0}."),
        ("Upd.WhatInclusion", "o que Atualizar tudo muda", "what Update All changes"),
        ("Upd.RowLeftOutThisGame", "Fora de Atualizar tudo neste jogo.", "Left out of Update All in this game."),
        ("Upd.RowLeftOutAllGames", "Fora de Atualizar tudo em todos os jogos (Configurações).", "Left out of Update All in every game (Settings)."),
        ("Upd.RowNotFollowed", "Não passa sozinho para a versão mais recente neste jogo.", "Not moved to the newest version automatically in this game."),
        ("Upd.UpdateAllExcluded", " · {0} deixado(s) de fora (sua escolha)", " · {0} left out (your choice)"),
        ("Upd.UpdateAllExcludedUnreadable", " · {0} deixado(s) de fora: não é possível ler o arquivo de inclusão em atualizações", " · {0} left out: the update-inclusion file cannot be read"),
        ("Upd.RowLeftOutUnreadable", "Fora de Atualizar tudo: não é possível ler o arquivo de inclusão em atualizações.", "Left out of Update All: the update-inclusion file cannot be read."),
        ("Upd.RowNotFollowedUnreadable", "Não passa sozinho para a versão mais recente: não é possível ler o arquivo de inclusão em atualizações.", "Not moved to the newest version automatically: the update-inclusion file cannot be read."),
        ("Upd.DialogUnreadable", "Não é possível ler o arquivo de inclusão em atualizações ({0}). Até que ele possa ser lido, Atualizar tudo e as atualizações em segundo plano deixam tudo de fora em todos os jogos. Corrija ou apague esse arquivo para escolher de novo.", "The update-inclusion file cannot be read ({0}). Until it can, Update All and the background updates leave everything out in every game. Fix or delete that file to choose again."),
