        ("Nv.TitleTip", "Definido pela camada NVIDIA do Proton (dxvk-nvapi) toda vez que o jogo inicia. Requer o Proton 10 ou mais recente.", "Set through Proton's NVIDIA layer (dxvk-nvapi) each time the game starts. Needs Proton 10 or newer."),
        ("Nv.SrPreset", "Preset do DLSS", "DLSS preset"),
        ("Nv.SrPresetTip", "Troca o modelo de upscaling do DLSS. J/K usam o transformer de 1ª geração (DLSS 4.0); L/M, o de 2ª geração (DLSS 4.5). Recomendado pela NVIDIA escolhe por resolução.", "Overrides the DLSS upscaling model. J/K use the first-generation transformer (DLSS 4.0); L/M the second generation (DLSS 4.5). NVIDIA Recommended picks one per resolution."),
        ("Nv.SrScale", "Escala de renderização", "Render scale"),
        ("Nv.ScaleTip", "Troca a escala de renderização do DLSS. Desligado = o jogo decide; Personalizado aceita de 33 a 100%.", "Overrides the DLSS render scale. Off = the game decides; Custom takes 33 to 100%."),
        ("Nv.RrPreset", "Preset do Ray Reconstruction", "Ray Reconstruction preset"),
