        ("Nrc.FixD3DCompilerWinetricks", "na linha D3DCompiler 47 da seção Perfil do ReShade, use o botão do Winetricks. Procurar só escolhe a DLL da Microsoft para a próxima vez que o RHI configurar o ReShade ou o DLSS5 Feeder.", "on the D3DCompiler 47 line of the ReShade profile section, use the Winetricks button. Browse only chooses Microsoft's DLL for the next time RHI sets up ReShade or the DLSS5 Feeder."),
        ("Nrc.FixD3DCompilerBrowse", "na linha D3DCompiler 47 da seção Perfil do ReShade, escolha a DLL da Microsoft com Procurar; o RHI a coloca na próxima vez que configurar o ReShade ou o DLSS5 Feeder.", "on the D3DCompiler 47 line of the ReShade profile section, choose Microsoft's DLL with Browse; RHI puts it in the next time it sets up ReShade or the DLSS5 Feeder."),
        ("Nrc.FixRemove", "confira a linha da DLL do Neural Rendering acima; se continuar acontecendo, remova {0} na linha dele em Componentes gerenciados.", "check the Neural Rendering DLL line above; if it keeps happening, remove {0} on its row in Managed components."),
        ("Nrc.FixAnyForCard", "uma versão feita para esta placa", "a version made for this card"),
        ("Nrc.FixFeederAgain", "escolha {0} na lista NR DLL em Versões NR, na seção Perfil do ReShade; depois remova {1} na linha dele em Componentes gerenciados e coloque-o de novo: este {1} antigo só usa a DLL escolhida quando é colocado.", "choose {0} in the NR DLL list under NR versions in the ReShade profile section, then remove {1} on its row in Managed components and add it again: this older {1} takes the chosen DLL only when it is added."),
        ("Nrc.FixScalerFirst", "primeiro remova o NR Cost Scaler na linha dele em Versões NR, na seção Perfil do ReShade: enquanto ele envolve a DLL do Neural Rendering, o RHI não altera nada por baixo dele. Depois abra esta página de novo.", "first remove NR Cost Scaler on its row under NR versions in the ReShade profile section: while it wraps the Neural Rendering DLL, RHI changes nothing under it. Then open this page again."),
        ("Nrc.FixSelectFirst", "selecione este jogo na biblioteca e abra esta página de novo: o RHI indica o controle a usar depois de examinar os arquivos do jogo.", "select this game in the library and open this page again: RHI names the control to use once it has looked at the game's files."),
        ("Nrc.FixNoRemove", "confira a linha da DLL do Neural Rendering acima; o RHI não pode remover {0} neste jogo agora (a linha dele em Componentes gerenciados diz por quê).", "check the Neural Rendering DLL line above; RHI cannot remove {0} in this game right now (its row in Managed components says why)."),
        ("Nrc.FixNoMethod", "confira a linha da DLL do Neural Rendering acima; o RHI não configurou nenhum método de Neural Rendering neste jogo para remover.", "check the Neural Rendering DLL line above; RHI set up no Neural Rendering method in this game to remove."),
        ("Nrc.FixChangedOutside", "a DLL do Neural Rendering foi alterada fora do RHI, então o RHI a deixa como está; coloque você mesmo uma feita para esta placa no lugar dela.", "the Neural Rendering DLL was changed outside RHI, so RHI leaves it as it is; put one made for this card in its place yourself."),
        ("Nrc.FixNoDll", "o RHI não encontrou nenhuma DLL do Neural Rendering neste jogo para trocar; o Neural Rendering precisa de uma feita para esta placa ao lado do executável do jogo.", "RHI found no Neural Rendering DLL in this game to swap; Neural Rendering needs one made for this card beside the game's executable."),
